import fs from 'fs';
import path from 'path';
import { errorMessage } from '../utils/errorMessage';

export interface AgentSkill {
  filePath: string;
  content: string;
  marker: string;
}

export type SkillResult =
  { ok: true; changed: boolean } | { ok: false; error: string };

export const hasAgentSkill = ({ filePath, marker }: AgentSkill): boolean => {
  try {
    return (
      fs.lstatSync(filePath).isFile() &&
      fs.readFileSync(filePath, 'utf8').includes(marker)
    );
  } catch {
    return false;
  }
};

export const writeAgentSkill = (skill: AgentSkill): SkillResult => {
  const { filePath, content } = skill;
  try {
    const existing = fs.lstatSync(filePath, { throwIfNoEntry: false });
    if (existing && !hasAgentSkill(skill)) {
      return {
        ok: false,
        error: `A user-managed skill already exists at ${filePath}. Move or rename it before installing Rivet's shortcut.`,
      };
    }
    if (existing && fs.readFileSync(filePath, 'utf8') === content) {
      return { ok: true, changed: false };
    }
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
    fs.writeFileSync(filePath, content, 'utf8');
    return { ok: true, changed: true };
  } catch (error) {
    return { ok: false, error: errorMessage(error) };
  }
};

export const removeAgentSkill = (skill: AgentSkill): SkillResult => {
  if (!hasAgentSkill(skill)) return { ok: true, changed: false };
  try {
    fs.unlinkSync(skill.filePath);
    return { ok: true, changed: true };
  } catch (error) {
    return { ok: false, error: errorMessage(error) };
  }
};
